  width: min(100%, 1080px);
  margin: 0 auto;
}

.gh-private-session .gh-hero {
  margin-bottom: 56px;
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(135deg, var(--gh-cream-light), var(--gh-cream));
  border-top: 3px solid var(--gh-green-soft);
  border-radius: 0 0 26px 26px;
}

.gh-private-session .gh-eyebrow {
  margin: 0 0 12px;
  color: var(--gh-green);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.gh-private-session .gh-hero-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.75rem, 4vw, 2.65rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-private-session .gh-hero-copy {
  max-width: 760px;
  margin: 24px auto 0;
  font-size: clamp(1rem, 2vw, 1.16rem);
}

.gh-private-session .gh-section {
  margin: 0 0 64px;
}

.gh-private-session .gh-lead {
  max-width: 820px;
  margin: 0 auto;
  padding: 38px 44px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-private-session .gh-heading {
  margin: 0 0 30px;
  padding-bottom: 13px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 2rem);
  font-weight: 500;
  text-align: center;
  border-bottom: 1px solid var(--gh-line);
}

.gh-private-session .gh-heading::after {
  display: block;
  width: 80px;
  height: 3px;
  margin: 13px auto -16px;
  background: var(--gh-green-soft);
  content: "";
}

.gh-private-session .gh-check-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 22px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gh-private-session .gh-check-list li {
  position: relative;
  padding: 17px 18px 17px 48px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 12px;
}

.gh-private-session .gh-check-list li::before {
  position: absolute;
  top: 17px;
  left: 18px;
  color: var(--gh-green);
  font-weight: 700;
  content: "✓";
}

.gh-private-session .gh-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.gh-private-session .gh-card {
  padding: 30px 25px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-private-session .gh-card-number {
  display: grid;
  width: 44px;
  height: 44px;
  margin: 0 auto 15px;
  color: #fff;
  font-weight: 500;
  place-items: center;
  background: var(--gh-green-soft);
  border-radius: 50%;
}

.gh-private-session .gh-card-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: 1.12rem;
  font-weight: 500;
  text-align: center;
}

.gh-private-session .gh-card p {
  margin: 0;
}

.gh-private-session .gh-flow {
  display: grid;
  gap: 16px;
  margin: 0;
  padding: 0;
  counter-reset: gh-step;
  list-style: none;
}

.gh-private-session .gh-flow li {
  position: relative;
  min-height: 72px;
  padding: 18px 20px 18px 84px;
  background: #fff;
  border-left: 4px solid var(--gh-green-soft);
  border-radius: 10px;
  box-shadow: 0 7px 24px rgba(85, 93, 89, 0.07);
  counter-increment: gh-step;
}

.gh-private-session .gh-flow li::before {
  position: absolute;
  top: 16px;
  left: 22px;
  color: var(--gh-green);
  font-size: 0.88rem;
  font-weight: 700;
  content: "STEP " counter(gh-step);
}

.gh-private-session .gh-details {
  overflow: hidden;
  margin: 0;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-private-session .gh-details-row {
  display: grid;
  grid-template-columns: 180px 1fr;
  border-bottom: 1px solid var(--gh-line);
}

.gh-private-session .gh-details-row:last-child {
  border-bottom: 0;
}

.gh-private-session .gh-details dt,
.gh-private-session .gh-details dd {
  margin: 0;
  padding: 18px 22px;
}

.gh-private-session .gh-details dt {
  color: var(--gh-text);
  font-weight: 400;
  background: var(--gh-green-pale);
}

.gh-private-session .gh-price {
  color: var(--gh-green);
  font-size: 1.35rem;
  font-weight: 700;
}

.gh-private-session .gh-note {
  margin: 18px 0 0;
  font-size: 0.9rem;
}

.gh-private-session .gh-message {
  padding: 42px;
  text-align: center;
  background: var(--gh-cream);
  border-radius: 20px;
}

.gh-private-session .gh-message p {
  max-width: 780px;
  margin: 0 auto;
}

.gh-private-session .gh-cta {
  padding: 54px 30px;
  text-align: center;
  background: var(--gh-green-pale);
  border-radius: 24px;
}

.gh-private-session .gh-cta-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 1.9rem);
  font-weight: 500;
}

.gh-private-session .gh-cta p {
  margin: 0 0 24px;
}

.gh-private-session .gh-button {
  display: inline-flex;
  min-width: 230px;
  min-height: 58px;
  padding: 12px 28px;
  align-items: center;
  justify-content: center;
  color: #fff !important;
  font-weight: 400;
  text-decoration: none !important;
  background: var(--gh-green-soft);
  border: 1px solid var(--gh-green-soft);
  border-radius: 2px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.gh-private-session .gh-button:hover,
.gh-private-session .gh-button:focus {
  color: #fff !important;
  opacity: 0.86;
  transform: translateY(-1px);
}

@media (max-width: 767px) {
  .gh-private-session {
    font-size: 16px;
  }

  .gh-private-session .gh-hero {
    margin-bottom: 40px;
    padding: 48px 20px;
  }

  .gh-private-session .gh-section {
    margin-bottom: 48px;
  }

  .gh-private-session .gh-lead,
  .gh-private-session .gh-message {
    padding: 28px 22px;
    text-align: left;
  }

  .gh-private-session .gh-check-list,
  .gh-private-session .gh-card-grid {
    grid-template-columns: 1fr;
  }

  .gh-private-session .gh-details-row {
    grid-template-columns: 1fr;
  }

  .gh-private-session .gh-details dt {
    padding-bottom: 8px;
  }

  .gh-private-session .gh-details dd {
    padding-top: 8px;
  }

  .gh-private-session .gh-flow li {
    padding: 54px 18px 18px;
  }

  .gh-private-session .gh-flow li::before {
    top: 13px;
    left: 18px;
  }
}

